def balanced(s: str) -> bool:
    matching = {
        ")": "(",
        "]": "[",
        "}": "{",
    }
    stack = []

    for ch in s:
        if ch in "([{":
            stack.append(ch)
        elif ch in ")]}":
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()

    return not stack


import pytest


@pytest.mark.parametrize(
    "s, expected",
    [
        ("", True),
        ("()", True),
        ("[]", True),
        ("{}", True),
        ("([]{})", True),
        ("([{}])", True),
        ("(]", False),
        ("([)]", False),
        ("((", False),
        (")(", False),
        ("a(b[c]d)e", True),
        ("abc", True),
    ],
)
def test_balanced(s, expected):
    assert balanced(s) == expected

