def balanced(s: str) -> bool:
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    for ch in s:
        if ch in '([{':
            stack.append(ch)
        elif ch in ')]}':
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack


import pytest


def test_empty_string():
    assert balanced("") is True


def test_single_open_paren():
    assert balanced("(") is False


def test_single_close_brace():
    assert balanced("}") is False


def test_simple_balanced():
    assert balanced("()") is True


def test_mismatched_types():
    assert balanced("{[}]}") is False


def test_extra_closing():
    assert balanced("())") is False


def test_extra_opening():
    assert balanced("(((") is False


def test_nested_all_types():
    assert balanced("(([]{}))") is True


def test_no_brackets():
    assert balanced("hello world") is True


def test_crossed_brackets():
    assert balanced("([)]") is False


def test_multiple_groups():
    assert balanced("{[()]}{}") is True


def test_deeply_nested():
    assert balanced("((({[[{}}]]}))") is True
